'use strict';
const $=id=>document.getElementById(id), STORAGE='jibun-company-v1';
const difficulties={easy:{name:'かんたん',exp:300,icon:'☀'},normal:{name:'ふつう',exp:500,icon:'✦'},hard:{name:'がんばる',exp:800,icon:'⚡'}};
const day=()=>new Date().toLocaleDateString('sv-SE');
const initial=()=>({exp:0,day:day(),today:0,sales:0,tasks:[{id:'first1',name:'洗濯する',difficulty:'easy'},{id:'first2',name:'メールを返す',difficulty:'normal'},{id:'first3',name:'歯磨きする',difficulty:'easy'}]});
let state;try{state=JSON.parse(localStorage.getItem(STORAGE))}catch{}if(!state||!Number.isFinite(state.exp)||!Array.isArray(state.tasks))state=initial();
let busy=false,sound=false,audio;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function daily(){if(state.day!==day()){state.day=day();state.today=0;state.sales=0}}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state))}catch{}}
function growth(exp){let level=1,cost=1000,remaining=exp;while(remaining>=cost){remaining-=cost;level++;cost=level*1000}return{level,cost,remaining}}
function render(){daily();const g=growth(state.exp);$('level').textContent=g.level;$('exp').textContent=g.remaining.toLocaleString();$('goal').textContent=g.cost.toLocaleString();$('progress').style.width=(g.remaining/g.cost*100)+'%';$('percent').textContent=Math.floor(g.remaining/g.cost*100)+'%';$('today').textContent=state.today;$('sales').textContent=state.sales.toLocaleString();$('count').textContent=state.tasks.length;$('office').className='office '+(g.level>=3?'lv3':g.level===2?'lv2':'');$('unlock').textContent=g.level===1?'🌿 観葉植物をお迎え':g.level===2?'💻 PCと棚を導入':'✦ 会社がもっと成長';$('office-note').textContent=g.level===1?'小さな一歩から、大きな会社へ。':g.level===2?'緑のあるオフィス。いい感じ。':'社長、会社らしくなってきました。';$('tasks').replaceChildren();for(const task of state.tasks){const d=difficulties[task.difficulty]||difficulties.normal;const button=document.createElement('button');button.className='task';button.setAttribute('aria-label',task.name+'を完了する。報酬'+d.exp+' EXP');const circle=document.createElement('span');circle.className='check';circle.textContent='✓';const details=document.createElement('span');details.className='task-details';const name=document.createElement('span');name.className='task-name';name.textContent=task.name;const badge=document.createElement('span');badge.className='task-difficulty';badge.textContent=d.icon+' '+d.name;details.append(name,badge);const reward=document.createElement('span');reward.className='task-exp';reward.textContent='+'+d.exp;const small=document.createElement('small');small.textContent='COMPANY EXP';reward.append(small);button.append(circle,details,reward);button.onclick=()=>complete(task.id);$('tasks').append(button)}if(!state.tasks.length){const e=document.createElement('div');e.className='empty';e.textContent='✦ 全案件、完了！社長、おつかれさま。\n次のビジネスチャンスを見つけよう。';$('tasks').append(e)}save()}
function tone(kind){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const notes=kind==='level'?[523,659,784,1047,1319]:kind==='complete'?[523,659,784,1047]:[392,523,784];notes.forEach((freq,i)=>{const osc=audio.createOscillator(),gain=audio.createGain();osc.type='triangle';osc.frequency.value=freq;gain.gain.setValueAtTime(0,audio.currentTime+i*.09);gain.gain.linearRampToValueAtTime(.11,audio.currentTime+i*.09+.015);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+i*.09+.24);osc.connect(gain);gain.connect(audio.destination);osc.start(audio.currentTime+i*.09);osc.stop(audio.currentTime+i*.09+.25)})}catch{}}
$('sound').onclick=()=>{sound=!sound;$('sound').querySelector('span').textContent=sound?'ON':'OFF';$('sound').setAttribute('aria-label','効果音を'+(sound?'オフ':'オン')+'にする');if(sound)tone('order')};
const wait=ms=>new Promise(resolve=>setTimeout(resolve,ms));
function confetti(duration,amount){if(reduced)return;const c=$('confetti'),ctx=c.getContext('2d');if(!ctx)return;const w=innerWidth,h=innerHeight,dpr=Math.min(devicePixelRatio||1,2);c.width=w*dpr;c.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);const colors=['#fff5b5','#fffdf1','#f7a8ce','#70a3dc','#f2894e','#527958'];const pieces=Array.from({length:amount},()=>({x:w/2,y:h*.43,vx:(Math.random()-.5)*25,vy:-Math.random()*22-3,rot:Math.random()*6,size:5+Math.random()*7,color:colors[Math.floor(Math.random()*colors.length)]}));let start,previous;function frame(t){start??=t;const dt=Math.min((t-(previous||t))/16.67,2);previous=t;ctx.clearRect(0,0,w,h);for(const p of pieces){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=.22*dt;p.rot+=.09*dt;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.rot);ctx.fillStyle=p.color;ctx.fillRect(-p.size/2,-p.size/2,p.size,p.size*.6);ctx.restore()}if(t-start<duration)requestAnimationFrame(frame);else ctx.clearRect(0,0,w,h)}requestAnimationFrame(frame)}
async function celebrate(kind,name,value,from){const overlay=$('celebration');overlay.hidden=false;overlay.className='celebration '+(kind==='complete'?'complete':kind==='level'?'levelup':'');$('celebrate-kicker').textContent=kind==='order'?'A NEW CHANCE!':kind==='complete'?'GREAT JOB, BOSS!':'YOUR COMPANY IS GROWING';$('celebrate-icon').textContent=kind==='order'?'✦':kind==='complete'?'✓':'♛';$('celebrate-title').textContent=kind==='order'?'新規案件獲得！':kind==='complete'?'案件完了！！':'COMPANY LEVEL UP!';$('celebrate-name').textContent=name;$('celebrate-message').textContent=kind==='order'?'完了時の報酬。さあ、ひと仕事！':kind==='complete'?'本日の売上 +'+value.toLocaleString()+' EXP':'あなたの会社が少し大きくなりました。';$('celebrate-hint').textContent=kind==='order'?'LET’S GET TO WORK.':kind==='complete'?'小さな「できた」に、大きな拍手。':'新しいオフィスを見てみよう。';$('reward').replaceChildren();const number=document.createElement('span'),unit=document.createElement('small');$('reward').append(number,unit);if(kind==='level'){number.textContent='Lv.'+from+' → Lv.'+value;unit.textContent=value===2?'🌿 観葉植物が仲間入り':value===3?'💻 PCと棚が仲間入り':'会社がさらに成長！'}else{unit.textContent='COMPANY EXP';const start=performance.now();function tick(now){const progress=reduced?1:Math.min((now-start)/650,1);number.textContent='+'+Math.round(value*(1-Math.pow(1-progress,3))).toLocaleString();if(progress<1)requestAnimationFrame(tick)}requestAnimationFrame(tick)}overlay.focus();if(!reduced){document.querySelector('.app').classList.add('shake');setTimeout(()=>document.querySelector('.app').classList.remove('shake'),450)}tone(kind);if(navigator.vibrate&&!reduced)navigator.vibrate(kind==='complete'?[30,40,60]:30);confetti(1800,kind==='order'?65:145);await wait(reduced?1100:kind==='order'?1750:2200);overlay.hidden=true}
$('new-task').onclick=()=>{if(busy)return;$('new-dialog').showModal();setTimeout(()=>$('task-name').focus(),60)};$('close-dialog').onclick=()=>$('new-dialog').close();$('new-dialog').onclick=e=>{if(e.target===$('new-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};
$('task-form').onsubmit=async e=>{e.preventDefault();if(busy)return;const name=$('task-name').value.trim();if(!name){$('task-name').setCustomValidity('案件名を入力してください');$('task-name').reportValidity();return}busy=true;const difficulty=new FormData(e.target).get('difficulty');const id=globalThis.crypto?.randomUUID?.()||Date.now()+'-'+Math.random();state.tasks.push({id,name,difficulty});save();$('new-dialog').close();e.target.reset();render();await celebrate('order',name,difficulties[difficulty].exp);busy=false;$('new-task').focus()};$('task-name').oninput=()=>$('task-name').setCustomValidity('');
async function complete(id){if(busy)return;const index=state.tasks.findIndex(t=>t.id===id);if(index<0)return;busy=true;daily();const task=state.tasks[index],d=difficulties[task.difficulty]||difficulties.normal,old=growth(state.exp).level;state.tasks.splice(index,1);state.exp+=d.exp;state.today++;state.sales+=d.exp;save();render();await celebrate('complete',task.name,d.exp);const next=growth(state.exp).level;if(next>old){await wait(180);await celebrate('level','おめでとう、社長！',next,old)}busy=false;render();$('today').parentElement.classList.remove('pop');void $('today').offsetWidth;$('today').parentElement.classList.add('pop');($('tasks').querySelector('button')||$('new-task')).focus()}
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!busy)render()});render();
